{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://volmit.com/gloss/holograms.schema.json",
  "title": "Gloss Hologram Document",
  "type": "object",
  "required": [
    "schemaVersion",
    "revision",
    "anchor"
  ],
  "properties": {
    "preset": {
      "type": [
        "string",
        "null"
      ],
      "minLength": 1,
      "description": "Named preset from this collection in presets.json; document fields override inherited values."
    },
    "schemaVersion": {
      "type": "integer",
      "const": 3
    },
    "revision": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991
    },
    "anchor": {
      "type": "object",
      "required": [
        "world",
        "position"
      ],
      "properties": {
        "world": {
          "type": "string",
          "minLength": 1
        },
        "position": {
          "$ref": "#/$defs/vector3"
        }
      }
    },
    "lines": {
      "description": "Authored lines, top to bottom. A string is a text row; an object carries an item, head, block or entity drawn under the text column.",
      "type": "array",
      "items": {
        "$ref": "#/$defs/line"
      }
    },
    "pages": {
      "description": "Pages replacing lines. Each viewer reads one page; navigate with mode page.",
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "#/$defs/page"
      }
    },
    "actions": {
      "description": "Actions run when a viewer clicks the hologram's interaction box.",
      "type": "array",
      "maxItems": 32,
      "items": {
        "$ref": "#/$defs/action"
      }
    },
    "hitbox": {
      "$ref": "#/$defs/hitbox"
    },
    "style": {
      "$ref": "#/$defs/iconDisplayStyle"
    },
    "box": {
      "$ref": "#/$defs/box"
    },
    "yaw": {
      "type": "number",
      "minimum": -180,
      "maximum": 180,
      "default": 0
    },
    "pitch": {
      "type": "number",
      "minimum": -90,
      "maximum": 90,
      "default": 0
    },
    "show": {
      "$ref": "#/$defs/show"
    },
    "particleLayers": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "#/$defs/particleLayer"
      }
    },
    "viewDistance": {
      "type": "number",
      "minimum": 4,
      "maximum": 128,
      "default": 48
    },
    "refreshTicks": {
      "type": "integer",
      "minimum": 1,
      "maximum": 200,
      "default": 10
    },
    "variants": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "#/$defs/variant"
      },
      "default": [],
      "description": "First matching presentation by descending priority, then id. Omitted fields inherit the base presentation."
    },
    "refresh": {
      "$ref": "#/$defs/displayRefresh"
    }
  },
  "$defs": {
    "iconDisplayStyle": {
      "title": "Icon Display Style",
      "description": "Optional display-entity metadata shared by text, image, item, block, and custom-item icons. Packet entity icons do not accept this object.",
      "type": "object",
      "dependentRequired": {
        "blockLight": [
          "skyLight"
        ],
        "skyLight": [
          "blockLight"
        ]
      },
      "properties": {
        "billboard": {
          "type": "string",
          "enum": [
            "fixed",
            "vertical",
            "horizontal",
            "center"
          ],
          "default": "fixed"
        },
        "shadow": {
          "type": "boolean",
          "default": false
        },
        "seeThrough": {
          "type": "boolean",
          "default": false
        },
        "textAlignment": {
          "type": "string",
          "enum": [
            "center",
            "left",
            "right"
          ],
          "default": "center"
        },
        "backgroundArgb": {
          "type": "string",
          "pattern": "^#[0-9A-Fa-f]{8}$",
          "default": "#00000000"
        },
        "textOpacity": {
          "type": "integer",
          "minimum": 0,
          "maximum": 255,
          "default": 255
        },
        "lineWidth": {
          "type": "integer",
          "minimum": 1,
          "maximum": 16384,
          "default": 16384
        },
        "blockLight": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0,
          "maximum": 15
        },
        "skyLight": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0,
          "maximum": 15
        },
        "viewRange": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        },
        "shadowRadius": {
          "type": "number",
          "minimum": 0,
          "maximum": 64,
          "default": 0
        },
        "shadowStrength": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "default": 0
        },
        "cullingWidth": {
          "type": "number",
          "minimum": 0,
          "maximum": 4096,
          "default": 0
        },
        "cullingHeight": {
          "type": "number",
          "minimum": 0,
          "maximum": 4096,
          "default": 0
        },
        "glowColor": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^#[0-9A-Fa-f]{8}$"
        },
        "scaleX": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        },
        "scaleY": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        },
        "scaleZ": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        }
      },
      "additionalProperties": false
    },
    "particleLayer": {
      "type": "object",
      "required": [
        "id",
        "target",
        "geometry",
        "particle"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
        },
        "target": {
          "type": "object",
          "required": [
            "scope"
          ],
          "properties": {
            "scope": {
              "enum": [
                "projection",
                "component",
                "text",
                "line",
                "span",
                "label",
                "model",
                "local"
              ]
            },
            "name": {
              "type": "string",
              "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
            },
            "component": {
              "type": "string",
              "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
            },
            "line": {
              "type": "integer",
              "minimum": 1
            }
          }
        },
        "geometry": {
          "type": "object",
          "required": [
            "type"
          ],
          "properties": {
            "type": {
              "enum": [
                "point",
                "line",
                "polyline",
                "outline",
                "filledPlane",
                "cuboid",
                "letterBounds",
                "glyphOutline",
                "glyphFill"
              ]
            },
            "from": {
              "$ref": "#/$defs/vector3"
            },
            "to": {
              "$ref": "#/$defs/vector3"
            },
            "points": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/vector3"
              }
            },
            "width": {
              "type": "number",
              "minimum": 0,
              "maximum": 128
            },
            "height": {
              "type": "number",
              "minimum": 0,
              "maximum": 128
            },
            "depth": {
              "type": "number",
              "minimum": 0,
              "maximum": 128
            },
            "padding": {
              "type": "number",
              "minimum": 0,
              "maximum": 16
            },
            "spacing": {
              "type": "number",
              "minimum": 0.02,
              "maximum": 16
            }
          }
        },
        "placement": {
          "type": "object",
          "properties": {
            "layer": {
              "enum": [
                "behind",
                "front",
                "center"
              ]
            },
            "depth": {
              "type": "number",
              "minimum": 0,
              "maximum": 16
            },
            "offset": {
              "$ref": "#/$defs/vector3"
            }
          }
        },
        "particle": {
          "type": "object",
          "required": [
            "key"
          ],
          "properties": {
            "key": {
              "type": "string",
              "pattern": "^[a-z0-9_.-]+:[a-z0-9_./-]+$"
            },
            "color": {
              "type": "string",
              "pattern": "^#[0-9A-Fa-f]{6}$"
            },
            "size": {
              "type": "number",
              "minimum": 0.01,
              "maximum": 4
            },
            "count": {
              "type": "integer",
              "minimum": 1,
              "maximum": 64,
              "default": 1,
              "description": "Particles emitted at each sampled point; every particle counts against the emission budget."
            },
            "speed": {
              "type": "number",
              "minimum": 0,
              "maximum": 10,
              "default": 0,
              "description": "Particle velocity multiplier."
            },
            "spread": {
              "type": "array",
              "items": {
                "type": "number",
                "minimum": 0,
                "maximum": 16,
                "default": 0
              },
              "minItems": 3,
              "maxItems": 3,
              "default": [
                0,
                0,
                0
              ],
              "description": "Random particle offsets along the x, y and z axes."
            }
          }
        },
        "emission": {
          "type": "object",
          "properties": {
            "intervalTicks": {
              "type": "integer",
              "minimum": 1,
              "maximum": 200
            },
            "pattern": {
              "enum": [
                "steady",
                "chase",
                "pulse",
                "twinkle",
                "scan",
                "corners"
              ]
            },
            "periodTicks": {
              "type": "integer",
              "minimum": 1,
              "maximum": 72000
            },
            "seed": {
              "type": "integer"
            }
          }
        },
        "priority": {
          "type": "integer",
          "minimum": -1000,
          "maximum": 1000
        },
        "viewDistance": {
          "type": "number",
          "minimum": 4,
          "maximum": 128,
          "default": 48,
          "description": "Maximum distance in blocks at which this layer emits for a viewer."
        },
        "show": {
          "oneOf": [
            {
              "type": "boolean"
            },
            {
              "type": "string"
            }
          ],
          "default": true,
          "description": "Boolean or viewer condition controlling whether this layer emits."
        }
      }
    },
    "vector3": {
      "title": "3D Vector",
      "description": "Represents a 3D floating-point vector.",
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "type": "number"
      }
    },
    "box": {
      "type": "object",
      "properties": {
        "enabled": {
          "type": "boolean",
          "default": false
        },
        "padding": {
          "type": "integer",
          "minimum": 0,
          "maximum": 64,
          "default": 4
        },
        "borderWidth": {
          "type": "integer",
          "minimum": 0,
          "maximum": 16,
          "default": 1
        },
        "backgroundArgb": {
          "type": "string",
          "pattern": "^#[0-9A-Fa-f]{8}$",
          "default": "#B31B1B22"
        },
        "borderArgb": {
          "type": "string",
          "pattern": "^#[0-9A-Fa-f]{8}$",
          "default": "#FFAAAAAA"
        }
      }
    },
    "show": {
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "type": "string",
          "minLength": 1
        }
      ],
      "description": "Boolean or Gloss boolean expression. Entity variables include entity.name, named, type, health, maxHealth, healthPercent (0..100), damage, damaged, attack, armor, stackCount, distance, and insight.active. Viewer, world, server, time, permissions, groups, regions and integration functions use the shared condition scope."
    },
    "line": {
      "title": "Hologram Line",
      "description": "A text row, or an object with exactly one of text, item, head, block or entity.",
      "oneOf": [
        {
          "type": [
            "string",
            "null"
          ]
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "text": {
              "description": "Text row source, run through the text pipeline.",
              "type": "string"
            },
            "item": {
              "description": "Menu icon data drawn as an item display.",
              "type": "object"
            },
            "head": {
              "description": "Player name whose head is drawn.",
              "type": "string",
              "minLength": 1
            },
            "block": {
              "description": "Block key drawn as a block display.",
              "type": "string",
              "pattern": "^([a-z0-9_.-]+:)?[a-z0-9_./-]+$"
            },
            "entity": {
              "description": "Entity type drawn as a raw packet entity.",
              "type": "string",
              "minLength": 1
            },
            "show": {
              "$ref": "#/$defs/show",
              "description": "Per-viewer condition controlling visibility of text or object content."
            },
            "scale": {
              "description": "Row height in blocks for object lines.",
              "type": "number",
              "minimum": 0.01,
              "maximum": 64,
              "default": 1
            }
          }
        }
      ]
    },
    "page": {
      "title": "Hologram Page",
      "type": "object",
      "required": [
        "id",
        "lines"
      ],
      "properties": {
        "id": {
          "description": "Page id used by navigate targets.",
          "type": "string",
          "minLength": 1
        },
        "lines": {
          "description": "Lines shown while a viewer reads this page.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/line"
          }
        },
        "show": {
          "$ref": "#/$defs/show",
          "description": "Controls whether this viewer can display or navigate to this page."
        }
      }
    },
    "hitbox": {
      "title": "Hologram Hitbox",
      "description": "The interaction box spawned for viewers within range when the hologram declares actions.",
      "type": "object",
      "properties": {
        "width": {
          "description": "Box width in blocks.",
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 64,
          "default": 1.2
        },
        "height": {
          "description": "Box height per row in blocks.",
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 64,
          "default": 0.35
        },
        "perLine": {
          "description": "One box per rendered row, each carrying its line index.",
          "type": "boolean",
          "default": false
        }
      }
    },
    "action": {
      "title": "Hologram Action",
      "description": "Same shape as a menu action. Navigation additionally accepts mode page with target next, prev or a page id.",
      "type": "object",
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "description": "Action type.",
          "type": "string",
          "minLength": 1
        },
        "trigger": {
          "description": "Click binding. Omitted matches every accepted main-hand click.",
          "type": [
            "string",
            "null"
          ],
          "enum": [
            "any",
            "left_click",
            "right_click",
            "shift_left_click",
            "shift_right_click",
            null
          ]
        },
        "mode": {
          "description": "Navigation mode; page moves the clicking viewer between hologram pages.",
          "type": "string",
          "enum": [
            "push",
            "replace",
            "back",
            "home",
            "close",
            "page"
          ]
        },
        "target": {
          "description": "Navigation target; for mode page this is next, prev or a page id.",
          "type": "string"
        },
        "when": {
          "description": "Condition evaluated for the clicking player before this action runs.",
          "type": "string"
        },
        "cooldownTicks": {
          "description": "Per-player cooldown in ticks after this action runs.",
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "variantPresentation": {
      "type": "object",
      "properties": {
        "lines": {
          "description": "Authored lines, top to bottom. A string is a text row; an object carries an item, head, block or entity drawn under the text column.",
          "type": "array",
          "items": {
            "$ref": "#/$defs/line"
          }
        },
        "style": {
          "$ref": "#/$defs/iconDisplayStyle"
        },
        "box": {
          "$ref": "#/$defs/box"
        },
        "particleLayers": {
          "type": "array",
          "maxItems": 64,
          "items": {
            "$ref": "#/$defs/particleLayer"
          }
        }
      },
      "additionalProperties": false
    },
    "variant": {
      "type": "object",
      "required": [
        "id",
        "when",
        "presentation"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
        },
        "priority": {
          "type": "integer",
          "minimum": -1000,
          "maximum": 1000,
          "default": 0
        },
        "when": {
          "type": "string",
          "description": "Condition selecting this presentation for the viewer."
        },
        "presentation": {
          "$ref": "#/$defs/variantPresentation"
        }
      },
      "additionalProperties": false
    },
    "displayRefresh": {
      "type": "object",
      "description": "Independent display refresh intervals. Omitted fields retain the surface default cadence.",
      "properties": {
        "contentTicks": {
          "type": "integer",
          "minimum": 1,
          "maximum": 1200,
          "description": "Text content refresh interval; animation frames retain their own clock."
        },
        "visibilityTicks": {
          "type": "integer",
          "minimum": 1,
          "maximum": 1200,
          "description": "Visibility and presentation condition interval."
        },
        "motionTicks": {
          "type": "integer",
          "minimum": 1,
          "maximum": 1200,
          "description": "Motion-binding or persistent object and box refresh interval."
        }
      }
    }
  }
}
''',
  'gloss/gloss-inventories.schema.json': r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://volmit.com/gloss/inventories.schema.json",
  "title": "Gloss Inventory Menu Document",
  "description": "A chest menu at plugins/Gloss/inventories/<id>.json. Every click is cancelled and no player item ever enters the window.",
  "type": "object",
  "required": [
    "schemaVersion",
    "revision"
  ],
  "properties": {
    "preset": {
      "type": [
        "string",
        "null"
      ],
      "minLength": 1
    },
    "schemaVersion": {
      "type": "integer",
      "const": 1
    },
    "revision": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991
    },
    "refresh": {
      "type": "object",
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "dynamic",
            "always"
          ],
          "default": "dynamic"
        },
        "titleTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200,
          "default": 20
        },
        "slotsTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200,
          "default": 20
        },
        "conditionsTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200,
          "default": 20
        },
        "listTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200,
          "description": "Defaults to list.refreshTicks."
        }
      }
    },
    "title": {
      "description": "Window title, run through the text pipeline.",
      "type": "string"
    },
    "resolution": {
      "description": "Window size.",
      "type": "string",
      "enum": [
        "9x1",
        "9x2",
        "9x3",
        "9x4",
        "9x5",
        "9x6",
        "5x1",
        "3x3"
      ],
      "default": "9x3"
    },
    "mask": {
      "description": "One row per window row, one character per slot. A space is always empty.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "keys": {
      "description": "What each mask character draws.",
      "type": "object",
      "additionalProperties": {
        "$ref": "https://volmit.com/gloss/schema.json#/$defs/componentData"
      }
    },
    "slots": {
      "description": "Slot index to component; overrides whatever the mask drew there.",
      "type": "object",
      "propertyNames": {
        "pattern": "^[0-9]+$"
      },
      "additionalProperties": {
        "$ref": "https://volmit.com/gloss/schema.json#/$defs/componentData"
      }
    },
    "list": {
      "description": "Fills one mask character with pages of a template.",
      "type": "object",
      "required": [
        "area",
        "var",
        "source",
        "template"
      ],
      "properties": {
        "area": {
          "description": "The mask character this list fills.",
          "type": "string",
          "minLength": 1,
          "maxLength": 1
        },
        "var": {
          "description": "Loop variable bound for each entry.",
          "type": "string",
          "pattern": "^[a-z][a-z0-9_]*$"
        },
        "source": {
          "description": "Expression producing the entries.",
          "type": "string",
          "minLength": 1
        },
        "pageSize": {
          "description": "Entries per page; defaults to the size of the area.",
          "type": "integer",
          "minimum": 1
        },
        "template": {
          "$ref": "https://volmit.com/gloss/schema.json#/$defs/componentData"
        },
        "refreshTicks": {
          "description": "How often a viewer-dependent source is re-evaluated. 0 never refreshes.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        }
      }
    },
    "closeOnTeleport": {
      "description": "Closes the window when its viewer teleports. Default true.",
      "type": "boolean"
    },
    "show": {
      "description": "Condition deciding whether this document is offered to a viewer at all.",
      "type": [
        "boolean",
        "string"
      ]
    },
    "select": {
      "description": "Board-model selection: the highest matching priority wins, ties break on the lowest id.",
      "type": "object",
      "properties": {
        "priority": {
          "description": "Higher wins.",
          "type": "integer"
        },
        "when": {
          "description": "Condition offering this document.",
          "type": "string"
        }
      }
    },
    "variants": {
      "description": "Conditional replacements of title, mask, keys and slots. Nothing merges.",
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "id",
          "presentation"
        ],
        "properties": {
          "id": {
            "description": "Variant id.",
            "type": "string",
            "minLength": 1
          },
          "priority": {
            "description": "Higher wins.",
            "type": "integer"
          },
          "when": {
            "description": "Condition selecting this variant.",
            "type": "string"
          },
          "presentation": {
            "description": "The replacement window.",
            "type": "object",
            "properties": {
              "title": {
                "description": "Replacement title.",
                "type": "string"
              },
              "mask": {
                "description": "Replacement mask.",
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "keys": {
                "description": "Replacement key map.",
                "type": "object",
                "additionalProperties": {
                  "$ref": "https://volmit.com/gloss/schema.json#/$defs/componentData"
                }
              },
              "slots": {
                "description": "Replacement slot overrides.",
                "type": "object",
                "additionalProperties": {
                  "$ref": "https://volmit.com/gloss/schema.json#/$defs/componentData"
                }
              }
            }
          }
        }
      }
    },
    "actions": {
      "type": "object",
      "maxProperties": 256,
      "propertyNames": {
        "pattern": "^[A-Za-z0-9_-]{1,64}$"
      },
      "additionalProperties": {
        "type": "array",
        "items": {
          "type": "object"
        }
      },
      "description": "Named action lists invoked with call. Cycles, more than 32 nested calls and expanded documents over 100000 JSON nodes are rejected."
    }
  }
}
''',
