          }
        },
        "surfaces": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "nametags": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "channels": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "strings": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "leaderboards": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "inventories": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "markers": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "nameplates": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "waypoints": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
            "$ref": "#/$defs/preset"
          }
        },
        "behaviors": {
          "type": "object",
          "propertyNames": {
            "pattern": "^(?!.*\\.\\.)(?!.*[/\\\\])\\S.*$"
          },
          "additionalProperties": {
