  }
}
''',
  'gloss/gloss.schema.json': r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://volmit.com/gloss/schema.json",
  "title": "Gloss Menu Config",
  "description": "Defines a Gloss hologram menu and all its components. Documents live in plugins/Gloss/menus/ and are hot reloaded. Documentation grade only: the Java parser is the format's source of truth. See the Gloss docs pages /gloss/09-menus, /gloss/10-components-hitboxes, /gloss/11-icons and /gloss/12-actions in the central VolmitSoftware/docs repo.",
  "type": "object",
  "required": [
    "offset",
    "components"
  ],
  "properties": {
    "offset": {
      "description": "Offset from the player's feet location (Player#getLocation), which acts as the menu centre. Component rotation pivots on the eye; the X component is negated on load. Not scaled by uiScale.",
      "$ref": "#/$defs/vector3"
    },
    "lockPosition": {
      "description": "Defines whether the player is able to move while a menu is open, or will be frozen in place.",
      "type": "boolean"
    },
    "followPlayer": {
      "description": "Defines whether the menu follows the player, or will be frozen in place.",
      "type": "boolean"
    },
    "maxDistance": {
      "description": "Defines the maximum distance between the player and menu before it closes.",
      "type": "number"
    },
    "closeOnDeath": {
      "description": "Defines whether the menu closes when the player dies. Defaults to false.",
      "type": "boolean"
    },
    "closeOnTeleport": {
      "description": "Defines whether the menu closes when the player teleports. Defaults to false. A teleport that leaves the menu's world or its range closes the menu regardless.",
      "type": "boolean"
    },
    "particleLayers": {
      "description": "Viewer-targeted particle effects attached to this in-world menu projection.",
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "#/$defs/particleLayer"
      }
    },
    "components": {
      "description": "A list of menu components present in this menu.",
      "type": "array",
      "items": {
        "$ref": "#/$defs/component"
      }
    },
    "show": {
      "description": "Boolean or expression controlling visibility of the menu.",
      "$ref": "#/$defs/show"
    },
    "vars": {
      "title": "Session Variable Defaults",
      "description": "Starting values for session.<name>. Each value is a constant expression; anything that needs live state is ignored.",
      "type": "object",
      "additionalProperties": {
        "type": "string"
      }
    },
    "actions": {
      "type": "object",
      "maxProperties": 256,
      "propertyNames": {
        "pattern": "^[A-Za-z0-9_-]{1,64}$"
      },
      "additionalProperties": {
        "type": "array",
        "items": {
          "$ref": "#/$defs/action"
        }
      },
      "description": "Named action lists invoked with call. Cycles, more than 32 nested calls and expanded documents over 100000 JSON nodes are rejected."
    }
  },
  "$defs": {
    "particleLayer": {
      "type": "object",
      "required": [
        "id",
        "target",
        "geometry",
        "particle"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
        },
        "target": {
          "type": "object",
          "required": [
            "scope"
          ],
          "properties": {
            "scope": {
              "enum": [
                "projection",
                "component",
                "text",
                "line",
                "span",
                "label",
                "model",
                "local",
                "world"
              ]
            },
            "name": {
              "type": "string",
              "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
            },
            "component": {
              "type": "string",
              "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
            },
            "line": {
              "type": "integer",
              "minimum": 1
            }
          }
        },
        "geometry": {
          "type": "object",
          "required": [
            "type"
          ],
          "properties": {
            "type": {
              "enum": [
                "point",
                "line",
                "polyline",
                "outline",
                "filledPlane",
                "cuboid",
                "letterBounds",
                "glyphOutline",
                "glyphFill"
              ]
            },
            "from": {
              "$ref": "#/$defs/particleAnchor"
            },
            "to": {
              "$ref": "#/$defs/particleAnchor"
            },
            "points": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/particleAnchor"
              }
            },
            "width": {
              "type": "number",
              "minimum": 0,
              "maximum": 128
            },
            "height": {
              "type": "number",
              "minimum": 0,
              "maximum": 128
            },
            "depth": {
              "type": "number",
              "minimum": 0,
              "maximum": 128
            },
            "padding": {
              "type": "number",
              "minimum": 0,
              "maximum": 16
            },
            "spacing": {
              "type": "number",
              "minimum": 0.02,
              "maximum": 16
            }
          }
        },
        "placement": {
          "type": "object",
          "properties": {
            "layer": {
              "enum": [
                "behind",
                "front",
                "center"
              ]
            },
            "depth": {
              "type": "number",
              "minimum": 0,
              "maximum": 16
            },
            "offset": {
              "$ref": "#/$defs/vector3"
            }
          }
        },
        "particle": {
          "type": "object",
          "required": [
            "key"
          ],
          "properties": {
            "key": {
              "type": "string",
              "pattern": "^[a-z0-9_.-]+:[a-z0-9_./-]+$"
            },
            "color": {
              "type": "string",
              "pattern": "^#[0-9A-Fa-f]{6}$"
            },
            "size": {
              "type": "number",
              "minimum": 0.01,
              "maximum": 4
            },
            "count": {
              "type": "integer",
              "minimum": 1,
              "maximum": 64,
              "default": 1,
              "description": "Particles emitted at each sampled point; every particle counts against the emission budget."
            },
            "speed": {
              "type": "number",
              "minimum": 0,
              "maximum": 10,
              "default": 0,
              "description": "Particle velocity multiplier."
            },
            "spread": {
              "type": "array",
              "items": {
                "type": "number",
                "minimum": 0,
                "maximum": 16,
                "default": 0
              },
              "minItems": 3,
              "maxItems": 3,
              "default": [
                0,
                0,
                0
              ],
              "description": "Random particle offsets along the x, y and z axes."
            }
          }
        },
        "emission": {
          "type": "object",
          "properties": {
            "intervalTicks": {
              "type": "integer",
              "minimum": 1,
              "maximum": 200
            },
            "pattern": {
              "enum": [
                "steady",
                "chase",
                "pulse",
                "twinkle",
                "scan",
                "corners"
              ]
            },
            "periodTicks": {
              "type": "integer",
              "minimum": 1,
              "maximum": 72000
            },
            "seed": {
              "type": "integer"
            }
          }
        },
        "priority": {
          "type": "integer",
          "minimum": -1000,
          "maximum": 1000
        },
        "viewDistance": {
          "type": "number",
          "minimum": 4,
          "maximum": 128,
          "default": 48,
          "description": "Maximum distance in blocks at which this layer emits for a viewer."
        },
        "show": {
          "oneOf": [
            {
              "type": "boolean"
            },
            {
              "type": "string"
            }
          ],
          "default": true,
          "description": "Boolean or viewer condition controlling whether this layer emits."
        }
      }
    },
    "particleAnchor": {
      "title": "Particle Anchor",
      "description": "One end of a particle geometry: a coordinate in the target's frame, or, under the world scope only, the role name viewer or subject, or an object naming an entity to follow.",
      "oneOf": [
        {
          "$ref": "#/$defs/vector3"
        },
        {
          "type": "string",
          "enum": [
            "viewer",
            "subject"
          ]
        },
        {
          "type": "object",
          "required": [
            "entity"
          ],
          "properties": {
            "entity": {
              "type": "string",
              "pattern": "^[0-9a-fA-F-]{36}$"
            }
          }
        }
      ]
    },
    "vector3": {
      "title": "3D Vector",
      "description": "Represents a 3D floating-point vector.",
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "type": "number"
      }
    },
    "component": {
      "title": "Gloss Component Object",
      "description": "Defines the basic properties of a component.",
      "type": "object",
      "required": [
        "id",
        "offset",
        "data"
      ],
      "properties": {
        "id": {
          "description": "A unique identifier for this menu option.",
          "type": "string"
        },
        "offset": {
          "description": "The offset relative to the menu's center point.",
          "$ref": "#/$defs/vector3"
        },
        "data": {
          "description": "The type and associated data of the object.",
          "$ref": "#/$defs/componentData"
        },
        "show": {
          "description": "Boolean or expression controlling visibility of this component.",
          "$ref": "#/$defs/show"
        },
        "motion": {
          "description": "Moves and resizes this component's existing displays without respawning them.",
          "$ref": "#/$defs/componentMotion"
        }
      }
    },
    "componentMotion": {
      "title": "Component Motion Object",
      "description": "Numbers or expressions re-read every tick while the component is open. The viewer's client eases each change over ticks.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "x": {
          "description": "Added to the offset on this axis, in menu blocks before uiScale.",
          "$ref": "#/$defs/motionValue"
        },
        "y": {
          "description": "Added to the offset on this axis, in menu blocks before uiScale.",
          "$ref": "#/$defs/motionValue"
        },
        "z": {
          "description": "Added to the offset on this axis, in menu blocks before uiScale.",
          "$ref": "#/$defs/motionValue"
        },
        "scale": {
          "description": "Multiplies the icon's size and hitbox. Values below 0.001 use 0.001. Entity icons keep their size.",
          "$ref": "#/$defs/motionValue"
        },
        "ticks": {
          "description": "How long the client takes to ease to a new value. 0 jumps there at once. Accepted range: 0 through 59.",
          "oneOf": [
            {
              "type": "integer",
              "minimum": 0,
              "maximum": 59
            },
            {
              "type": "string"
            }
          ],
          "default": 3
        }
      }
    },
    "motionValue": {
      "oneOf": [
        {
          "type": "number"
        },
        {
          "type": "string"
        }
      ]
    },
    "componentData": {
      "title": "Component Data Object",
      "description": "Defines the type and data of a component.",
      "type": "object",
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "type": "string",
          "description": "Defines the type of component.",
          "enum": [
            "button",
            "decoration",
            "toggle",
            "list",
            "slider",
            "field",
            "tabs"
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "button"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/buttonComponent"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "decoration"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/decoComponent"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "toggle"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/toggleComponent"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "list"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/listComponent"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "slider"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/sliderComponent"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "field"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/fieldComponent"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "tabs"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/tabsComponent"
          }
        }
      ]
    },
    "action": {
      "title": "Component Action Data Object",
      "description": "Describes the actual effects of a interact-able component.",
      "type": "object",
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "type": "string",
          "description": "Defines the type of action.",
          "enum": [
            "command",
            "sound",
            "message",
            "teleport",
            "connect",
            "navigate",
            "title",
            "actionbar",
            "bossbar",
            "surface",
            "close",
            "inventory",
            "setSession",
            "prompt",
            "dialog",
            "book",
            "give",
            "take",
            "economy",
            "delay",
            "call",
            "sequence",
            "parallel",
            "repeat",
            "if",
            "switch",
            "chance",
            "cooldown",
            "emit",
            "broadcast",
            "effect",
            "particle",
            "stop",
            "setState",
            "addState",
            "clearState",
            "sky",
            "camera",
            "glow"
          ]
        },
        "trigger": {
          "description": "Optional click binding. Omitted or null matches every accepted main-hand click.",
          "default": "any",
          "oneOf": [
            {
              "type": "string",
              "enum": [
                "any",
                "left_click",
                "right_click",
                "shift_left_click",
                "shift_right_click"
              ]
            },
            {
              "type": "null"
            }
          ]
        },
        "when": {
          "description": "Optional condition evaluated for the clicking player each time the action would run; false skips this action and continues with the next. Same syntax as show conditions.",
          "type": "string"
        },
        "cooldownTicks": {
          "description": "Optional per-player cooldown in ticks after this action runs; while it is active the action is skipped and the list continues. Omitted or 0 means no cooldown.",
          "type": "integer",
          "minimum": 0
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "command"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/commandAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "sound"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/soundAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "message"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/messageAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "teleport"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/teleportAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "connect"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/connectAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "navigate"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/navigationAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "title"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/titleAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "actionbar"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/actionBarAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "bossbar"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/bossBarAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "close"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/closeAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "inventory"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/inventoryAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "setSession"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/setSessionAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "prompt"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/promptAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "book"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/bookAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "give"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/giveAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "take"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/takeAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "economy"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/economyAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "delay"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/delayAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "sequence"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/sequenceAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "parallel"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/parallelAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "repeat"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/repeatAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "if"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/ifAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "switch"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/switchAction"
          }
