        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "addState"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/addStateAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "clearState"
              }
            }
          },
          "then": {
