          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "sky"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/skyAction"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "camera"
              }
            }
          },
          "then": {
