          }
        }
      ]
    },
    "glowAction": {
      "title": "Entity Glow Action Data Object",
      "description": "Outlines an entity for the clicking player alone. Tags stack per purpose and the highest priority decides the colour shown.",
      "type": "object",
      "required": [
        "color"
      ],
      "properties": {
        "target": {
          "description": "Whose outline: viewer, subject, or an entity uuid. Defaults to the clicking player.",
          "type": "string"
        },
        "color": {
          "description": "Named text colour applied to the outline and the team.",
          "type": "string",
          "minLength": 1,
          "maxLength": 32
        },
        "ticks": {
          "description": "Ticks the tag lives for. Zero keeps it until something untags it.",
          "type": "integer",
          "minimum": 0
        },
        "purpose": {
          "description": "Owner name for this tag, so two owners never clear each other.",
          "type": "string",
          "minLength": 1,
          "maxLength": 64
        },
        "priority": {
          "description": "Higher priority wins when several tags target the same entity for the same viewer.",
          "type": "integer"
        }
      }
    },
    "cameraAction": {
      "title": "Camera Ride Action Data Object",
      "description": "Takes the clicking player on a spectator ride along a Catmull-Rom path. Terminates the action list: the ride owns the player until it ends.",
      "type": "object",
      "required": [
        "path"
      ],
      "properties": {
        "path": {
          "description": "Ordered camera nodes. Each node's durationTicks is the time spent travelling to the next one; the last node's is ignored.",
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": [
              "x",
              "y",
              "z"
            ],
            "properties": {
              "x": {
                "type": "number"
              },
              "y": {
                "type": "number"
              },
              "z": {
                "type": "number"
              },
              "yaw": {
                "type": "number"
              },
              "pitch": {
                "type": "number",
                "minimum": -90,
                "maximum": 90
              },
              "durationTicks": {
                "type": "integer",
                "minimum": 0
              }
            }
          }
        },
        "skippable": {
          "description": "Ends the ride when the rider sneaks. Defaults to true.",
          "type": "boolean"
        },
        "letterbox": {
          "description": "Asks for black bars while the ride runs. Ignored when no surface provider is installed, and never sent to Bedrock viewers.",
          "type": "boolean"
        }
      }
    },
    "skyAction": {
      "title": "Per-Viewer Sky Action Data Object",
      "description": "Claims the clicking player's time, weather and world border under a purpose. Overrides stack by purpose and the newest wins; releasing one hands the sky back to the previous owner.",
      "type": "object",
      "required": [
        "purpose"
      ],
      "properties": {
        "purpose": {
          "description": "Owner name for this claim. Releasing the same purpose restores what was showing before it.",
          "type": "string",
          "minLength": 1,
          "maxLength": 64
        },
        "time": {
          "description": "Day-clock tick shown to this viewer, or \"reset\" to release the purpose.",
          "type": [
            "integer",
            "string"
          ]
        },
        "weather": {
          "description": "Weather shown to this viewer, or \"reset\" to release the purpose. Bukkit has no per-player thunder, so thunder renders as downfall.",
          "type": "string",
          "enum": [
            "clear",
            "rain",
            "downfall",
            "thunder",
            "storm",
            "reset"
          ]
        },
        "border": {
          "description": "Per-viewer world border. Sent through Paper's Bukkit-typed API when it exists and as border packets on Spigot.",
          "type": "object",
          "required": [
            "centerX",
            "centerZ",
            "size"
          ],
          "properties": {
            "centerX": {
              "type": "number"
            },
            "centerZ": {
              "type": "number"
            },
            "size": {
              "type": "number",
              "minimum": 1
            },
            "warningBlocks": {
              "type": "integer",
              "minimum": 0,
              "maximum": 512
            }
          }
        },
        "fadeTicks": {
          "description": "Ticks the time takes to walk from the world's own time to the override, along the shorter arc of the day clock. Zero jumps.",
          "type": "integer",
          "minimum": 0,
          "maximum": 72000
        }
      }
    },
    "iconDisplayStyle": {
      "title": "Icon Display Style",
      "description": "Optional display-entity metadata shared by text, image, item, block, and custom-item icons. Packet entity icons do not accept this object.",
      "type": "object",
      "dependentRequired": {
        "blockLight": [
          "skyLight"
        ],
        "skyLight": [
          "blockLight"
        ]
      },
      "properties": {
        "billboard": {
          "type": "string",
          "enum": [
            "fixed",
            "vertical",
            "horizontal",
            "center"
          ],
          "default": "fixed"
        },
        "shadow": {
          "type": "boolean",
          "default": false
        },
        "seeThrough": {
          "type": "boolean",
          "default": false
        },
        "textAlignment": {
          "type": "string",
          "enum": [
            "center",
            "left",
            "right"
          ],
          "default": "center"
        },
        "backgroundArgb": {
          "type": "string",
          "pattern": "^#[0-9A-Fa-f]{8}$",
          "default": "#00000000"
        },
        "textOpacity": {
          "type": "integer",
          "minimum": 0,
          "maximum": 255,
          "default": 255
        },
        "lineWidth": {
          "type": "integer",
          "minimum": 1,
          "maximum": 16384,
          "default": 16384
        },
        "blockLight": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0,
          "maximum": 15
        },
        "skyLight": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0,
          "maximum": 15
        },
        "viewRange": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        },
        "shadowRadius": {
          "type": "number",
          "minimum": 0,
          "maximum": 64,
          "default": 0
        },
        "shadowStrength": {
          "type": "number",
          "minimum": 0,
          "maximum": 1,
          "default": 0
        },
        "cullingWidth": {
          "type": "number",
          "minimum": 0,
          "maximum": 4096,
          "default": 0
        },
        "cullingHeight": {
          "type": "number",
          "minimum": 0,
          "maximum": 4096,
          "default": 0
        },
        "glowColor": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^#[0-9A-Fa-f]{8}$"
        },
        "scaleX": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        },
        "scaleY": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        },
        "scaleZ": {
          "type": "number",
          "minimum": 0.01,
          "maximum": 64,
          "default": 1
        }
      },
      "additionalProperties": false
    },
    "icon": {
      "title": "Component Icon Data Object",
      "description": "Defines the visual parts of a component.",
      "type": "object",
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "type": "string",
          "description": "Defines the type of icon.",
          "enum": [
            "text",
            "textImage",
            "animatedTextImage",
            "item",
            "block",
            "customItem",
            "entity",
            "playerHead"
          ]
        },
        "style": {
          "description": "Optional display styling. Omitted uses fixed, fully visible, unlit-override defaults at uniform scale 1.",
          "oneOf": [
            {
              "$ref": "#/$defs/iconDisplayStyle"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "text"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/textIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "textImage"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/textImageIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "animatedTextImage"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/animatedTextImageIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "item"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/itemIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "block"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/blockIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "customItem"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/customItemIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "entity"
              }
            }
          },
          "then": {
            "allOf": [
              {
                "$ref": "#/$defs/entityIcon"
              },
              {
                "not": {
                  "required": [
                    "style"
                  ]
                }
              }
            ]
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "playerHead"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/playerHeadIcon"
          }
        }
      ]
    },
    "hitbox": {
      "title": "Clickable Hitbox",
      "description": "Optional click-plane dimensions, anchor and displacement in blocks before uiScale is applied.",
      "type": "object",
      "minProperties": 1,
      "dependentRequired": {
        "width": [
          "height"
        ],
        "height": [
          "width"
        ]
      },
      "properties": {
        "width": {
          "description": "Click-plane width in blocks at uiScale 1.",
          "type": "number",
          "exclusiveMinimum": 0
        },
        "height": {
          "description": "Click-plane height in blocks at uiScale 1.",
          "type": "number",
          "exclusiveMinimum": 0
        },
        "offset": {
          "description": "Displacement from the selected anchor in right, up, forward blocks at uiScale 1.",
          "$ref": "#/$defs/vector3"
        },
        "anchor": {
          "description": "Whether offset is relative to the clickable component or the menu centre. Menu anchoring detaches icon and plane movement.",
          "type": "string",
          "enum": [
            "button",
            "menu"
          ]
        }
      },
      "additionalProperties": false
    },
    "buttonComponent": {
      "title": "Button Component Data Object",
      "description": "Defines the data for a button component.",
      "type": "object",
      "required": [
        "actions",
        "icon"
      ],
      "properties": {
        "highlightModifier": {
          "description": "Menu-local travel toward the viewer at uiScale 1.",
          "type": "number"
        },
        "hoverDurationTicks": {
          "description": "Ticks used to enter and leave the hovered pose. Defaults to 4; zero is instant.",
          "type": "integer",
          "minimum": 0,
          "maximum": 40
        },
        "hoverEasing": {
          "description": "Easing curve used for hover entry and exit. Defaults to ease_out_cubic.",
          "type": "string",
          "enum": [
            "linear",
            "ease_out_cubic",
            "ease_in_out_cubic",
            "back_out"
          ]
        },
        "actions": {
          "description": "Defines what happens upon a interaction.",
          "type": "array",
          "items": {
            "$ref": "#/$defs/action"
          }
        },
        "icon": {
          "description": "Defines the visual part of the component.",
          "$ref": "#/$defs/icon"
        },
        "hitbox": {
          "description": "Optional dimensions and displacement for the click plane. Omitted dimensions remain automatic; omitted offset remains icon-aligned.",
          "$ref": "#/$defs/hitbox"
        },
        "tooltip": {
          "description": "Secondary pane shown after the viewer has hovered this button for delayTicks.",
          "type": "object",
          "properties": {
            "delayTicks": {
              "description": "Hover ticks before the pane appears.",
              "type": "integer",
              "minimum": 0
            },
            "lines": {
              "description": "Lines drawn in the pane.",
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "style": {
              "$ref": "#/$defs/iconDisplayStyle"
            },
            "box": {
              "$ref": "#/$defs/box"
            }
          }
        }
      }
    },
    "decoComponent": {
      "title": "Decoration Component Data Object",
      "description": "Defines the data for a decorative component.",
      "type": "object",
      "required": [
        "icon"
      ],
      "properties": {
        "icon": {
          "description": "Defines the visual parts of a component.",
          "$ref": "#/$defs/icon"
        }
      }
    },
    "toggleComponent": {
      "title": "Toggle Component Data Object",
      "description": "Defines the data for a toggle component.",
      "type": "object",
      "required": [
        "condition",
        "expectedValue",
        "trueActions",
        "falseActions",
        "trueIcon",
        "falseIcon"
      ],
      "properties": {
        "highlightModifier": {
          "description": "Menu-local travel toward the viewer at uiScale 1.",
          "type": "number"
        },
        "hoverDurationTicks": {
          "description": "Ticks used to enter and leave the hovered pose. Defaults to 4; zero is instant.",
          "type": "integer",
          "minimum": 0,
          "maximum": 40
        },
        "hoverEasing": {
          "description": "Easing curve used for hover entry and exit. Defaults to ease_out_cubic.",
          "type": "string",
          "enum": [
            "linear",
            "ease_out_cubic",
            "ease_in_out_cubic",
            "back_out"
          ]
        },
        "condition": {
          "description": "Defines what placeholder value is used to determine the toggles initial state.",
          "type": "string"
        },
        "expectedValue": {
          "description": "Defines what the condition is checked against to determine the toggles initial state.",
          "type": "string"
        },
        "trueActions": {
          "description": "Defines what happens upon a interaction that enters the true state, so upon a interaction while the toggle is false.",
          "type": "array",
          "items": {
            "$ref": "#/$defs/action"
          }
        },
        "falseActions": {
          "description": "Defines what happens upon a interaction that enters the false state, so upon a interaction while the toggle is true.",
          "type": "array",
          "items": {
            "$ref": "#/$defs/action"
          }
        },
        "trueIcon": {
          "description": "Defines the visual part of the component while the toggle is in the true state.",
          "$ref": "#/$defs/icon"
        },
        "falseIcon": {
          "description": "Defines the visual part of the component while the toggle is in the false state.",
          "$ref": "#/$defs/icon"
        },
        "hitbox": {
          "description": "Optional stable click plane shared by both toggle icon states.",
          "$ref": "#/$defs/hitbox"
        }
      }
    },
    "commandAction": {
      "title": "Command Action Data Object",
      "description": "Defines the data for a command action.",
      "type": "object",
      "required": [
        "command"
      ],
      "properties": {
        "command": {
          "description": "Defines the command run by this action. %player% and %player_name% become the clicking player's name before player or server dispatch.",
          "type": "string",
          "minLength": 1,
          "pattern": "[^\\s/]"
        },
        "source": {
          "description": "Defines the source of this command. Defaults to \"player\", so the command runs as the clicking player unless \"server\" is written explicitly.",
          "type": "string",
          "enum": [
            "server",
            "player"
          ]
        }
      }
    },
    "soundAction": {
      "title": "Sound Action Data Object",
      "description": "Defines the data for a sound action.",
      "type": "object",
      "required": [
        "sound"
      ],
      "properties": {
        "sound": {
          "description": "Defines the sound played by this action. An unknown sound key is logged when the component resolves its actions and the action is dropped.",
          "type": "string"
        },
        "source": {
          "description": "Defines the audio channel of this sound. Defaults to \"master\".",
          "type": "string",
          "enum": [
            "master",
            "music",
            "record",
            "weather",
            "block",
            "hostile",
            "neutral",
            "player",
            "ambient",
            "voice"
          ]
        },
        "volume": {
          "description": "Defines the volume modifier for this sound. Defaults to 1.0.",
          "type": "number"
        },
        "pitch": {
          "description": "Defines the pitch modifier for this sound. Defaults to 1.0.",
          "type": "number"
        }
      }
    },
    "messageAction": {
      "title": "Player Message Action Data Object",
      "description": "Sends a MiniMessage-formatted message to the clicking player.",
      "type": "object",
      "required": [
        "message"
      ],
      "properties": {
        "message": {
          "description": "MiniMessage text sent to the player. %player% and PlaceholderAPI placeholders are resolved for the clicking player before parsing.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        }
      }
    },
    "teleportAction": {
      "title": "Player Teleport Action Data Object",
      "description": "Teleports the clicking player asynchronously to an already-loaded namespaced world.",
      "type": "object",
      "required": [
        "world",
        "x",
        "y",
        "z",
        "yaw",
        "pitch"
      ],
      "properties": {
        "world": {
          "description": "Explicit lowercase namespace:key of an already-loaded Bukkit world.",
          "type": "string",
          "maxLength": 255,
          "pattern": "^[a-z0-9._-]+:[a-z0-9/._-]+$"
        },
        "x": {
          "description": "Finite destination X coordinate.",
          "type": "number"
        },
        "y": {
          "description": "Finite destination Y coordinate.",
          "type": "number"
        },
        "z": {
          "description": "Finite destination Z coordinate.",
          "type": "number"
        },
        "yaw": {
          "description": "Finite destination yaw in degrees.",
          "type": "number"
        },
        "pitch": {
          "description": "Finite destination pitch in degrees.",
          "type": "number"
        }
      }
    },
    "connectAction": {
      "title": "Proxy Server Connect Action Data Object",
      "description": "Requests a BungeeCord-compatible proxy connection for the clicking player.",
      "type": "object",
      "required": [
        "server"
      ],
      "properties": {
        "server": {
          "description": "Configured proxy server name. Only letters, numbers, dot, underscore, and hyphen are accepted.",
          "type": "string",
          "minLength": 1,
          "maxLength": 64,
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$"
        }
      }
    },
    "titleAction": {
      "title": "Title Action Data Object",
      "description": "Shows a title and subtitle to the clicking player through the shared HUD compositor, so a higher-priority title from another plugin is not overwritten. Continues the action list.",
      "type": "object",
      "required": [
        "title"
      ],
      "properties": {
        "title": {
          "description": "Title text. Runs through the full text pipeline for the clicking player.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "subtitle": {
          "description": "Optional subtitle text under the title. Omitted means no subtitle.",
          "type": "string"
        },
        "fadeInTicks": {
          "description": "Ticks the title fades in over. Defaults to 10.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "stayTicks": {
          "description": "Ticks the title stays fully visible. Defaults to 40.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "fadeOutTicks": {
          "description": "Ticks the title fades out over. Defaults to 10.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "priority": {
          "description": "Compositor priority this title bids with. Defaults to notice.",
          "type": "string",
          "enum": [
            "ambient",
            "notice",
            "status",
            "progress",
            "interactive",
            "modal",
            "pinned"
          ]
        }
      }
    },
    "actionBarAction": {
      "title": "Action Bar Action Data Object",
      "description": "Publishes one action bar segment for the clicking player through the shared HUD compositor, which merges it with segments other plugins publish. Continues the action list.",
      "type": "object",
      "required": [
        "text"
      ],
      "properties": {
        "text": {
          "description": "Action bar text. Runs through the full text pipeline for the clicking player.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "ticks": {
          "description": "Ticks the segment stays published before it expires. Defaults to 60.",
          "type": "integer",
          "minimum": 1,
          "maximum": 1200
        },
        "slots": {
          "description": "Compositor slots this segment may occupy. Defaults to center.",
