          "type": "array",
          "minItems": 1,
          "items": {
            "allOf": [
              {
                "$ref": "#/$defs/action"
              }
            ],
            "properties": {
              "atTicks": {
                "description": "Tick offset from the start of the sequence.",
                "type": "integer",
                "minimum": 0,
                "maximum": 1728000
              }
            }
          }
        },
        "skippable": {
          "description": "When true the viewer ends the sequence by sneaking, which runs onSkip.",
          "type": "boolean",
          "default": false
        },
        "once": {
          "description": "Player boolean state key set when the sequence completes; while it is true the sequence is skipped.",
          "type": "string",
          "pattern": "^[a-z][a-z0-9_.]*$"
        },
        "onSkip": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when a skippable sequence is ended early."
        }
      }
    },
    "parallelAction": {
      "title": "Parallel Action Data Object",
      "description": "Starts every branch as its own program and continues with the rest of the list immediately.",
      "type": "object",
      "required": [
        "branches"
      ],
      "properties": {
        "branches": {
          "description": "One action list per branch.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/actionList"
          }
        }
      }
    },
    "repeatAction": {
      "title": "Repeat Action Data Object",
      "description": "Runs steps up to times iterations. With everyTicks the loop suspends between iterations; without it the whole loop runs in one tick and is capped at 1024 iterations.",
      "type": "object",
      "required": [
        "times",
        "steps"
      ],
      "properties": {
        "times": {
          "description": "Maximum number of iterations.",
          "type": "integer",
          "minimum": 1,
          "maximum": 100000
        },
        "everyTicks": {
          "description": "Ticks between iterations. 0 or omitted runs every iteration in the same tick.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1728000,
          "default": 0
        },
        "steps": {
          "$ref": "#/$defs/actionList",
          "description": "The actions run on each iteration."
        },
        "while": {
          "description": "Boolean condition checked before each iteration; false ends the loop early.",
          "type": "string"
        }
      }
    },
    "ifAction": {
      "title": "If Action Data Object",
      "description": "Evaluates when in the action's condition scope and runs then or else.",
      "type": "object",
      "required": [
        "when"
      ],
      "properties": {
        "when": {
          "description": "Boolean condition. Same syntax as show conditions.",
          "type": "string",
          "minLength": 1
        },
        "then": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the condition is true."
        },
        "else": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the condition is false."
        }
      }
    },
    "switchAction": {
      "title": "Switch Action Data Object",
      "description": "Evaluates on, converts the result to text and runs the matching case, or default when nothing matches.",
      "type": "object",
      "required": [
        "on",
        "cases"
      ],
      "properties": {
        "on": {
          "description": "Expression whose value selects the case.",
          "type": "string",
          "minLength": 1
        },
        "cases": {
          "description": "Case value to action list.",
          "type": "object",
          "minProperties": 1,
          "additionalProperties": {
            "$ref": "#/$defs/actionList"
          }
        },
        "default": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when no case matches."
        }
      }
    },
    "chanceAction": {
      "title": "Chance Action Data Object",
      "description": "Rolls a percentage and runs then or else.",
      "type": "object",
      "required": [
        "percent"
      ],
      "properties": {
        "percent": {
          "description": "Chance of running then, from 0 to 100.",
          "type": "number",
          "minimum": 0,
          "maximum": 100
        },
        "then": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the roll succeeds."
        },
        "else": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the roll fails."
        }
      }
    },
    "cooldownAction": {
      "title": "Cooldown Action Data Object",
      "description": "Claims a named per-player cooldown. The first claim runs then; a claim inside the window runs else.",
      "type": "object",
      "required": [
        "key",
        "ticks"
      ],
      "properties": {
        "key": {
          "description": "Cooldown name, scoped to behaviors.",
          "type": "string",
          "minLength": 1
        },
        "ticks": {
          "description": "Length of the cooldown window in ticks.",
          "type": "integer",
          "minimum": 1,
          "maximum": 1728000
        },
        "then": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the cooldown was free."
        },
        "else": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run while the cooldown is active."
        }
      }
    },
    "emitAction": {
      "title": "Emit Action Data Object",
      "description": "Fires the emit trigger with this name. Emits nest at most eight deep before they are dropped with a warning.",
      "type": "object",
      "required": [
        "name"
      ],
      "properties": {
        "name": {
          "description": "Event name matched by an emit trigger.",
          "type": "string",
          "minLength": 1
        },
        "args": {
          "description": "Values readable as args.* in the entries that answer. A string wrapped in {{ }} is evaluated first.",
          "type": "object"
        }
      }
    },
    "broadcastAction": {
      "title": "Broadcast Action Data Object",
      "description": "Sends one message to several players at once.",
      "type": "object",
      "required": [
        "message"
      ],
      "properties": {
        "message": {
          "description": "MiniMessage text rendered for each recipient.",
          "type": "string",
          "minLength": 1
        },
        "scope": {
          "description": "Who receives it. Defaults to the whole server.",
          "type": "string",
          "enum": [
            "server",
            "world",
            "radius"
          ],
          "default": "server"
        },
        "radius": {
          "description": "Block radius around the viewer; required when scope is radius.",
          "type": "number",
          "exclusiveMinimum": 0
        },
        "permission": {
          "description": "Only players with this permission receive the message.",
          "type": "string"
        }
      }
    },
    "effectAction": {
      "title": "Potion Effect Action Data Object",
      "description": "Applies a potion effect to one of the trigger's roles.",
      "type": "object",
      "required": [
        "effect",
        "ticks"
      ],
      "properties": {
        "effect": {
          "description": "Potion effect key, such as minecraft:speed.",
          "type": "string",
          "pattern": "^([a-z0-9_.-]+:)?[a-z0-9_./-]+$"
        },
        "ticks": {
          "description": "Effect duration in ticks.",
          "type": "integer",
          "minimum": 1,
          "maximum": 1728000
        },
        "amplifier": {
          "description": "Effect amplifier; 0 is level one.",
          "type": "integer",
          "minimum": 0,
          "default": 0
        },
        "target": {
          "description": "Which role receives the effect.",
          "type": "string",
          "enum": [
            "viewer",
            "subject",
            "source"
          ],
          "default": "viewer"
        }
      }
    },
    "particleAction": {
      "title": "Particle Action Data Object",
      "description": "Spawns particles at one of the trigger's roles or at its location.",
      "type": "object",
      "required": [
        "particle"
      ],
      "properties": {
        "particle": {
          "description": "Particle key, such as minecraft:flame.",
          "type": "string",
          "pattern": "^([a-z0-9_.-]+:)?[a-z0-9_./-]+$"
        },
        "count": {
          "description": "How many particles to spawn.",
          "type": "integer",
          "minimum": 1,
          "default": 1
        },
        "offset": {
          "description": "Random spread in blocks around the anchor.",
          "type": "number",
          "minimum": 0,
          "default": 0
        },
        "at": {
          "description": "Where to spawn them.",
          "type": "string",
          "enum": [
            "viewer",
            "subject",
            "source",
            "location"
          ],
          "default": "viewer"
        }
      }
    },
    "stopAction": {
      "title": "Stop Action Data Object",
      "description": "Ends the surrounding action list. Nothing after it runs.",
      "type": "object",
      "required": [],
      "properties": {}
    },
    "setStateAction": {
      "title": "Set State Action Data Object",
      "description": "Writes one state value, coerced to the key's declared type.",
      "type": "object",
      "required": [
        "key",
        "value"
      ],
      "properties": {
        "key": {
          "description": "A state key declared by a behavior document.",
          "type": "string",
          "pattern": "^[a-z][a-z0-9_.]*$"
        },
        "value": {
          "description": "Expression evaluated in the action's condition scope; its result becomes the new value.",
          "type": "string",
          "minLength": 1
        },
        "target": {
          "description": "Whose value to write for a player-scoped or world-scoped key.",
          "type": "string",
          "enum": [
            "viewer",
            "subject",
            "source"
          ],
          "default": "viewer"
        }
      }
    },
    "addStateAction": {
      "title": "Add State Action Data Object",
      "description": "Adds to one number state value.",
      "type": "object",
      "required": [
        "key",
        "value"
      ],
      "properties": {
        "key": {
          "description": "A state key declared by a behavior document.",
          "type": "string",
          "pattern": "^[a-z][a-z0-9_.]*$"
        },
        "value": {
          "description": "Expression evaluated in the action's condition scope; its number result is added to the current value.",
          "type": "string",
          "minLength": 1
        },
        "target": {
          "description": "Whose value to write for a player-scoped or world-scoped key.",
          "type": "string",
          "enum": [
            "viewer",
            "subject",
            "source"
          ],
          "default": "viewer"
        }
      }
    },
    "clearStateAction": {
      "title": "Clear State Action Data Object",
      "description": "Returns one state value to the default its declaration gives.",
      "type": "object",
      "required": [
        "key"
      ],
      "properties": {
        "key": {
          "description": "A state key declared by a behavior document.",
          "type": "string",
          "pattern": "^[a-z][a-z0-9_.]*$"
        },
        "target": {
          "description": "Whose value to clear for a player-scoped or world-scoped key.",
          "type": "string",
          "enum": [
            "viewer",
            "subject",
            "source"
          ],
          "default": "viewer"
        }
      }
    },
    "dialogAction": {
      "type": "object",
      "description": "A native Java 1.21.6+ dialog. Terminal; buttons run their own actions with input.<key> values. Unsupported clients run unsupported.",
      "properties": {
        "title": {
          "type": "string"
        },
        "kind": {
          "enum": [
            "notice",
            "confirmation",
            "multi_action"
          ],
          "default": "notice"
        },
        "body": {
          "type": "array",
          "maxItems": 64,
          "items": {
            "type": "object",
            "properties": {
              "text": {
                "type": "string"
              },
              "width": {
                "type": "integer",
                "minimum": 1,
                "maximum": 1024,
                "default": 200
              }
            }
          }
        },
        "inputs": {
          "type": "array",
          "maxItems": 64,
          "items": {
            "type": "object",
            "required": [
              "key"
            ],
            "properties": {
              "key": {
                "type": "string",
                "pattern": "^[A-Za-z0-9_]{1,64}$"
              },
              "type": {
                "enum": [
                  "text",
                  "boolean",
                  "single_option",
                  "number_range"
                ]
              },
              "label": {
                "type": "string"
              },
              "width": {
                "type": "integer",
                "minimum": 1,
                "maximum": 1024,
                "default": 200
              },
              "labelVisible": {
                "type": "boolean",
                "default": true
              },
              "initial": {
                "type": [
                  "string",
                  "number",
                  "boolean"
                ]
              },
              "maxLength": {
                "type": "integer",
                "minimum": 1,
                "maximum": 4096,
                "default": 32
              },
              "maxLines": {
                "type": "integer",
                "minimum": 1,
                "maximum": 4096
              },
              "height": {
                "type": "integer",
                "minimum": 1,
                "maximum": 512
              },
              "options": {
                "type": "array",
                "minItems": 1,
                "maxItems": 64,
                "items": {
                  "type": "object",
                  "required": [
                    "id"
                  ],
                  "properties": {
                    "id": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 256
                    },
                    "label": {
                      "type": "string"
                    }
                  }
                }
              },
              "start": {
                "type": "number"
              },
              "end": {
                "type": "number"
              },
              "step": {
                "type": "number",
                "exclusiveMinimum": 0
              },
              "labelFormat": {
                "type": "string"
              }
            }
          }
        },
        "buttons": {
          "type": "array",
          "minItems": 1,
          "maxItems": 64,
          "items": {
            "type": "object",
            "properties": {
              "label": {
                "type": "string"
              },
              "tooltip": {
                "type": "string"
              },
              "width": {
                "type": "integer",
                "minimum": 1,
                "maximum": 1024,
                "default": 150
              },
              "actions": {
                "type": "array",
                "items": {
                  "$ref": "#/$defs/action"
                }
              }
            }
          }
        },
        "exitButton": {
          "type": "object",
          "properties": {
            "label": {
              "type": "string"
            },
            "tooltip": {
              "type": "string"
            },
            "width": {
              "type": "integer",
              "minimum": 1,
              "maximum": 1024,
              "default": 150
            },
            "actions": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/action"
              }
            }
          }
        },
        "escape": {
          "type": "boolean",
          "default": true
        },
        "columns": {
          "type": "integer",
          "minimum": 1,
          "maximum": 64,
          "default": 2
        },
        "timeoutTicks": {
          "type": "integer",
          "minimum": 1,
          "maximum": 72000,
          "default": 1200
        },
        "unsupported": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/action"
          }
        },
        "onTimeout": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/action"
          }
        }
      }
    },
    "surfaceAction": {
      "type": "object",
      "required": [
        "surface"
      ],
      "properties": {
        "surface": {
          "type": "string"
        },
        "audience": {
          "type": "object",
          "properties": {
            "scope": {
              "enum": [
                "viewer",
                "server",
                "world",
                "radius"
              ]
            },
            "radius": {
              "type": "number",
              "exclusiveMinimum": 0,
              "maximum": 4096
            },
            "when": {
              "type": [
                "string",
                "boolean"
              ]
            }
          }
        }
      }
    },
    "callAction": {
      "type": "object",
      "required": [
        "action"
      ],
      "properties": {
        "action": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]{1,64}$"
        }
      },
      "description": "Runs a named action list from this menu or inventory document, preserving trigger, when and cooldownTicks."
    }
  }
}
''',
  'gloss/source.json': r'''
{
  "description": "Gloss schemas copied unchanged for the GUI kinds Animus adopts. Animus never edits these files; when Gloss raises a version, copy the new file, update the commit and add support in an Animus release.",
  "repository": "VolmitSoftware/Gloss",
  "commit": "feb33148e3a0c66d755c1b9f982a2931c91d4522",
  "copied": "2026-11-04",
  "files": {
    "gloss-inventories.schema.json": {"kind": "inventory", "schemaVersion": 1, "animusFolder": "gui/inventories", "animusSchema": "../gui-inventory-v1.schema.json"},
    "gloss.schema.json": {"kind": "menu", "schemaVersion": null, "animusFolder": "gui/menus"},
    "gloss-holograms.schema.json": {"kind": "hologram", "schemaVersion": 3, "animusFolder": "gui/holograms"},
    "gloss-presets.schema.json": {"kind": "presets", "schemaVersion": 1, "animusFolder": "gui"}
  },
  "notCopied": {
    "text-animation": "Gloss text animations have no schema file; Animus validates them in TextAnimation (schemaVersion 1, folder gui/text-animations)."
  },
  "actions": {
    "supported": ["command", "sound", "message", "title", "actionbar", "close", "navigate", "inventory", "setSession", "give", "take", "economy", "delay", "sequence", "if", "switch", "chance", "cooldown", "stop", "call", "teleport", "bossbar", "broadcast", "effect", "particle", "parallel", "repeat"],
    "animus": ["animus:open-shop"],
    "refused": ["connect", "surface", "prompt", "dialog", "book", "emit", "setState", "addState", "clearState", "sky", "camera", "glow"]
  }
}
''',
  'gui-inventory-v1.schema.json': r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://animus.volmitsoftware.com/schema/gui-inventory-v1.schema.json",
  "title": "Animus chest GUI",
  "description": "gui/inventories/<namespace>/<name>.json, a Gloss inventories document (schemaVersion 1) read by Animus. The id comes from the file location. Gloss-only actions, holographic menu components and presets are refused. The Java GuiDocument parser is authoritative.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "revision": {
      "type": "integer",
      "minimum": 1,
      "maximum": 2147483647
    },
    "title": {
      "$ref": "#/$defs/template"
    },
    "resolution": {
      "enum": [
        "9x1",
        "9x2",
        "9x3",
        "9x4",
        "9x5",
        "9x6",
        "5x1",
        "3x3"
      ]
    },
    "mask": {
      "type": "array",
      "maxItems": 6,
      "items": {
        "type": "string",
        "maxLength": 9
      }
    },
    "keys": {
      "type": "object",
      "propertyNames": {
        "minLength": 1,
        "maxLength": 1
      },
      "additionalProperties": {
        "$ref": "#/$defs/component"
      }
    },
    "slots": {
      "type": "object",
      "propertyNames": {
        "pattern": "^[0-9]{1,2}$"
      },
      "additionalProperties": {
        "$ref": "#/$defs/component"
      }
    },
    "list": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "area": {
          "type": "string",
          "minLength": 1,
          "maxLength": 1
        },
        "var": {
          "type": "string"
        },
        "source": true,
        "pageSize": {
          "type": "integer",
          "minimum": 1
        },
        "template": {
          "$ref": "#/$defs/component"
        },
        "refreshTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        }
      }
    },
    "refresh": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "mode": {
          "enum": [
            "dynamic",
            "always"
          ]
        },
        "titleTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "slotsTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "conditionsTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "listTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        }
      }
    },
    "closeOnTeleport": {
      "type": "boolean"
    },
    "show": {
      "$ref": "#/$defs/condition"
    },
    "select": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "priority": {
          "type": "integer"
        },
        "when": {
          "type": "string"
        }
      }
    },
    "variants": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id"
        ],
        "properties": {
          "id": {
            "type": "string"
          },
          "priority": {
            "type": "integer"
          },
          "when": {
            "type": "string"
          },
          "presentation": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "title": {
                "$ref": "#/$defs/template"
              },
              "mask": {
                "type": "array",
                "items": {
                  "type": "string",
                  "maxLength": 9
                }
              },
              "keys": {
                "type": "object",
                "additionalProperties": {
                  "$ref": "#/$defs/component"
                }
              },
              "slots": {
                "type": "object",
                "additionalProperties": {
                  "$ref": "#/$defs/component"
                }
              }
            }
          }
        }
      }
    },
    "actions": {
      "type": "object",
      "maxProperties": 256,
      "propertyNames": {
        "pattern": "^[A-Za-z0-9_-]{1,64}$"
      },
      "additionalProperties": {
        "$ref": "#/$defs/actions"
      }
    },
    "preset": {
      "not": true,
      "description": "Gloss presets are not available in Animus; inline the preset's fields."
    }
  },
  "$defs": {
    "template": {
      "type": "string",
      "maxLength": 4096,
      "description": "Text with & codes, MiniMessage and {{ expr }} expressions."
    },
    "condition": {
      "type": [
        "boolean",
        "string"
      ],
      "description": "A boolean or an expression string."
    },
    "icon": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "enum": [
            "item",
            "playerHead"
          ],
          "description": "Holographic icons (text, block, entity) and customItem are refused."
        },
        "style": true,
        "item": {
          "$ref": "#/$defs/template"
        },
        "count": {
          "type": "integer",
          "minimum": 1,
          "maximum": 99
        },
        "customModelValue": {
          "type": "integer"
        },
        "name": {
          "$ref": "#/$defs/template"
        },
        "lore": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/template"
          }
        },
        "countFormat": true,
        "player": {
          "$ref": "#/$defs/template"
        },
        "refreshTicks": true
      }
    },
    "component": {
      "type": "object",
      "required": [
        "type"
      ],
      "properties": {
        "type": {
          "enum": [
            "button",
            "decoration",
            "toggle"
          ],
          "description": "list, slider, field and tabs are holographic menu components and are refused."
        },
        "show": {
          "$ref": "#/$defs/condition"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "button"
              }
            }
          },
          "then": {
            "required": [
              "icon",
              "actions"
            ],
            "propertyNames": {
              "enum": [
                "type",
                "show",
                "icon",
                "actions",
                "highlightModifier",
                "hoverDurationTicks",
